import React, { useEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, animate, motion, useMotionValue, useTransform } from "framer-motion";
import { ArrowRight, BookOpen, Check, ChevronDown, Clock3, Heart, MessageSquareText, Plus, RotateCcw, Search, Settings2, Shuffle, Target, Trophy, Volume2, X, List, Grid2X2 } from "lucide-react";
