type Subject = "英単語" | "漢字";
type Word = { id?: number; front: string; back: string; reading?: string | null; imageUrl?: string | null; exampleSentence?: string | null; exampleTranslation?: string | null };
type BookMap = Record<Subject, Array<{ id: string; name: string; words: Word[] }>>;
type SessionKind = "practice" | "test";
type Mode = "choose" | "settings" | "reviewChoose" | "list" | SessionKind | "timedOut" | "result";
type Order = "normal" | "reverse" | "random";
type Direction = "question" | "answer";
type Pool = "normal" | "mistakes";
type PracticeRating = "known" | "review" | "instant" | "slow";
type SwipeAxis = "right" | "left" | "up" | "down";

function offlineBooksKey(subject: "english" | "kanji") {
  return `studyverse-offline-wordbooks:${subject}`;
}

function readOfflineBooks(subject: "english" | "kanji") {
  try {
    const raw = window.localStorage.getItem(offlineBooksKey(subject));
    const parsed = raw ? JSON.parse(raw) : null;
    return Array.isArray(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
}

const ratingMeta: Record<PracticeRating, { label: string; shortLabel: string; symbol: string; description: string; tone: string }> = {
  known: { label: "GREAT / PERFECT", shortLabel: "右・GREAT / PERFECT", symbol: "○", description: "普通にわかった単語", tone: "text-cyan-600" },
  review: { label: "MISS / BAD", shortLabel: "左・MISS / BAD", symbol: "×", description: "わからなかった単語", tone: "text-violet-600" },
  instant: { label: "THINK / DELAY", shortLabel: "上・THINK / DELAY", symbol: "◎", description: "見た瞬間にわかった単語", tone: "text-amber-600" },
  slow: { label: "ESCAPE / AVOID", shortLabel: "下・ESCAPE / AVOID", symbol: "△", description: "わかっていたが答えるのに時間がかかった単語", tone: "text-orange-600" },
};

const swipeAxisFor = (deltaX: number, deltaY: number): { axis: SwipeAxis; rating: PracticeRating } => {
  if (Math.abs(deltaX) >= Math.abs(deltaY)) return deltaX >= 0 ? { axis: "right", rating: "known" } : { axis: "left", rating: "review" };
  return deltaY < 0 ? { axis: "up", rating: "instant" } : { axis: "down", rating: "slow" };
};


export type PracticeResumeDraft = {
  version: 1;
  subject: Subject;
  words: Word[];
  index: number;
  result: { known: number; review: number };
  missedWords: Word[];
  order: Order;
  direction: Direction;
  pool: Pool;
  training: boolean;
  repeat: boolean;
  savedAt: string;
};

const minutesFor = (count: number) => Math.max(5, Math.ceil(count / 10) * 5);
const formatClock = (seconds: number) => `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;

function SettingDropdown({ label, hint, value, onChange, options }: { label: string; hint: string; value: string | number; onChange: (value: string) => void; options: Array<{ value: string | number; label: string }> }) {
  return <section className="rounded-2xl bg-white/[.045] p-4"><p className="text-sm font-bold">{label}</p><p className="mt-1 text-xs text-slate-400">{hint}</p><select aria-label={label} value={value} onChange={event => onChange(event.target.value)} className="mt-3 w-full rounded-xl border border-white/15 bg-slate-950/35 px-3 py-3 text-sm font-semibold"><>{options.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</></select></section>;
}

function PracticeSwipeExit({ word, subject, showAnswer, rating, axis, originX, originY, repeat }: { word: Word; subject: Subject; showAnswer: boolean; rating: PracticeRating; axis: SwipeAxis; originX: number; originY: number; repeat: boolean }) {
  const destination = axis === "right" ? { x: 760, y: originY, rotate: 12 } : axis === "left" ? { x: -760, y: originY, rotate: -12 } : axis === "up" ? { x: originX, y: -760, rotate: 0 } : { x: originX, y: 760, rotate: 0 };
  const meta = ratingMeta[rating];
  return <motion.div initial={{ x: originX, y: originY, rotate: originX / 36, opacity: 1 }} animate={{ ...destination, opacity: 0.08 }} transition={{ duration: 0.3, ease: [0.23, 1, 0.32, 1] }} className="pointer-events-none glass-card absolute inset-x-0 top-0 z-10 flex h-full select-none flex-col justify-between rounded-[30px] p-6 text-slate-950 shadow-[0_24px_48px_rgba(0,0,0,.3)]"><div className="flex justify-between text-[10px] font-bold uppercase tracking-widest text-slate-400"><span>{subject === "漢字" ? "その他" : subject}</span><span>{showAnswer ? "answer" : "question"}</span></div><p className="my-auto text-center text-4xl font-extrabold tracking-[-.05em]">{showAnswer ? word.front : word.back}</p><p className={`text-center text-sm font-bold ${repeat ? "text-slate-400" : meta.tone}`}>{repeat ? "■" : `${meta.symbol} ${meta.label}`}</p></motion.div>;
}

