  const swipe = (rating: PracticeRating, axis: SwipeAxis) => { if (!active || advanceLock.current) return; pointerStart.current = null; setSwipePreview(null); if (exitTimer.current) window.clearTimeout(exitTimer.current); setSwipeExitCard({ word: active, showAnswer, rating, axis, originX: cardX.get(), originY: cardY.get() }); exitTimer.current = window.setTimeout(() => setSwipeExitCard(null), 310); cardX.set(0); cardY.set(0); finish(rating !== "review" && rating !== "slow", rating); };
